<template><section class="community-interactions" aria-label="Tương tác bài viết"><p v-if="loading" role="status">Đang tải tương tác…</p><p v-if="error" role="alert">{{ error }} <button type="button" class="button button-outline" :disabled="busy" @click="load">Thử lại</button></p>
  <div v-if="activity" class="community-actions"><template v-if="isAuthenticated"><button type="button" :disabled="busy" :aria-pressed="activity.liked" @click="react('like',!activity.liked)"><MarketIcon name="heart"/>{{ activity.liked?'Đã thích':'Thích' }} · {{ activity.likeCount }}</button><button type="button" :disabled="busy" :aria-pressed="activity.bookmarked" @click="react('bookmark',!activity.bookmarked)"><MarketIcon name="bookmark"/>{{ activity.bookmarked?'Đã lưu bài':'Lưu bài' }}</button></template><RouterLink v-else :to="{path:'/login',query:{redirect:'/community/posts/'+post.id}}">Đăng nhập để thích và lưu bài · {{ activity.likeCount }} lượt thích</RouterLink><span v-if="busy" role="status">Đang lưu tương tác…</span></div>
  <section v-if="activity?.acceptedAnswer" class="community-accepted"><h2>Giải pháp tác giả thấy hữu ích</h2><strong>{{ activity.acceptedAnswer.authorName }}</strong><p>{{ activity.acceptedAnswer.body }}</p><p class="community-hint">Do tác giả bài viết lựa chọn; không phải xác nhận chuyên môn hoặc xác nhận cây đã khỏi.</p></section>
  <div v-if="activity?.products?.length" class="community-linked-products"><h2>Sản phẩm tác giả liên kết</h2><p class="community-hint">Từ gian hàng do tác giả sở hữu. Bạn có thể tham khảo, không bắt buộc mua để tham gia thảo luận.</p><article v-for="product in activity.products" :key="product.id"><CatalogImage :src="product.imageUrl" :alt="product.name" ratio="1"/><div><RouterLink :to="'/products/'+product.id">{{ product.name }}</RouterLink><p>{{ money(product.price) }}</p><RouterLink :to="'/stores/'+product.storeId">{{ product.storeName }}</RouterLink></div></article></div>
</section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {useAuth} from '../../composables/useAuth.js';import {marketplaceRequest as request} from '../../services/marketplace.js';import MarketIcon from '../marketplace/MarketIcon.vue';import CatalogImage from '../marketplace/CatalogImage.vue';const props=defineProps({post:{type:Object,required:true}}),emit=defineEmits(['loaded','changed']),{isAuthenticated,user}=useAuth(),activity=ref(null),busy=ref(false),loading=ref(false),error=ref('');let generation=0;
const money=value=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(value);
async function load(){const ticket=++generation;loading.value=true;error.value='';activity.value=null;try{const result=await request('/community/posts/'+props.post.id+'/activity');if(ticket===generation){activity.value=result;emit('loaded',result);}}catch(e){if(ticket===generation)error.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
async function react(kind,enabled){if(busy.value)return;busy.value=true;error.value='';const ticket=generation;try{const result=await request('/account/community/posts/'+props.post.id+'/'+kind,enabled?'PUT':'DELETE');if(ticket===generation){activity.value=result;emit('changed',result);}}catch(e){if(ticket===generation)error.value=e.message;}finally{busy.value=false;}}
watch(()=>[props.post.id,props.post.revision,user.value?.id],load,{immediate:true});onBeforeUnmount(()=>generation++);defineExpose({load});
</script>
